        checkCurrentLayout(4, GAMES_NECKLACE_1);
        checkCurrentLayout(5, GAMES_NECKLACE_6);
        checkCurrentLayout(6, GAMES_NECKLACE_6);
        checkCurrentLayout(7, GAMES_NECKLACE_1);
    }

